					decay: 0,
					release: 0.3,
					releaseCurve: [1, 0, 1, 0],
					sustain: 1,
				}).toDestination();
				expect(env.attackCurve).to.deep.equal([0, 1, 0, 1]);
				env.triggerAttackRelease(0.3, 0.1);
			}, 0.8);
			buffer.forEach((sample, time) => {
				if (time > 0.4 && time < 0.5) {
					expect(sample).to.be.above(0);
				} else if (time < 0.1) {
