				expect(clock.state).to.equal("started");

				return (time) => {
					whenBetween(time, 0, 0.2, () => {
						expect(clock.state).to.equal("started");
					});

					whenBetween(time, 0.2, 0.4, () => {
						expect(clock.state).to.equal("paused");
