		expect(tickSignal.getTicksAtTime(0.75)).to.be.closeTo(1, 0.01);
		expect(tickSignal.getTicksAtTime(1)).to.be.closeTo(1.5, 0.01);
		expect(tickSignal.getTimeOfTick(1.5)).to.be.closeTo(1, 0.01);
