import { BaseContext } from "../context/BaseContext.js";
import { TicksClass } from "../type/Ticks.js";
import { Seconds, Ticks, Time } from "../type/Units.js";
import { GT, LT } from "../util/Math.js";
import type { TransportInstance as Transport } from "./Transport.js";
import { TransportEvent, TransportEventOptions } from "./TransportEvent.js";

interface TransportRepeatEventOptions extends TransportEventOptions {
	interval: Ticks;
	duration: Ticks;
}

/**
 * TransportRepeatEvent is an internal class used by Tone.Transport
 * to schedule repeat events. This class should not be instantiated directly.
 */
export class TransportRepeatEvent extends TransportEvent {
	/**
	 * When the event should stop repeating
	 */
	private duration: Ticks;

	/**
	 * The interval of the repeated event
	 */
	private _interval: Ticks;

	/**
	 * The ID of the current timeline event
	 */
	private _currentId = -1;

	/**
	 * The ID of the next timeline event
	 */
	private _nextId = -1;

	/**
	 * The time of the next event
	 */
	private _nextTick = this.time;

	/**
	 * a reference to the bound start method
	 */
	private _boundRestart = this._restart.bind(this);

	/**
	 * The audio context belonging to this event
	 */
	protected context: BaseContext;

	/**
	 * @param transport The transport object which the event belongs to
	 */
	constructor(
		transport: Transport,
		opts: Partial<TransportRepeatEventOptions>
	) {
		super(transport, opts);

		const options = Object.assign(TransportRepeatEvent.getDefaults(), opts);

		this.duration = options.duration;
		this._interval = options.interval;
		this._nextTick = options.time;
		this.transport.on("start", this._boundRestart);
		this.transport.on("loopStart", this._boundRestart);
		this.transport.on("ticks", this._boundRestart);
		this.context = this.transport.context;
		this._restart();
	}

	static getDefaults(): TransportRepeatEventOptions {
		return Object.assign({}, TransportEvent.getDefaults(), {
			duration: Infinity,
			interval: 1,
			once: false,
		});
	}

	/**
	 * Invoke the callback. Returns the tick time which
	 * the next event should be scheduled at.
	 * @param  time  The AudioContext time in seconds of the event
	 */
	invoke(time: Seconds): void {
		// create more events if necessary
		this._createEvents();
		// call the super class
		super.invoke(time);
	}

	/**
	 * Create an event on the transport on the nextTick
	 */
	private _createEvent(): number {
		if (LT(this._nextTick, this.floatTime + this.duration)) {
			return this.transport.scheduleOnce(
				this.invoke.bind(this),
				new TicksClass(this.context, this._nextTick).toSeconds()
			);
		}
		return -1;
	}

	/**
	 * Push more events onto the timeline to keep up with the position of the timeline
	 */
	private _createEvents(): void {
		// if the next tick is within the bounds set by "duration"
		if (
			LT(this._nextTick + this._interval, this.floatTime + this.duration)
		) {
			this._nextTick += this._interval;
			this._currentId = this._nextId;
			this._nextId = this.transport.scheduleOnce(
				this.invoke.bind(this),
				new TicksClass(this.context, this._nextTick).toSeconds()
			);
		}
	}

	/**
	 * Re-compute the events when the transport time has changed from a start/ticks/loopStart event
	 */
	private _restart(time?: Time): void {
		this.transport.clear(this._currentId);
		this.transport.clear(this._nextId);
		// start at the first event
		this._nextTick = this.floatTime;
		const ticks = this.transport.getTicksAtTime(time);
		if (GT(ticks, this.time)) {
			// the event is not being scheduled from the beginning and should be offset
			this._nextTick =
				this.floatTime +
				Math.ceil((ticks - this.floatTime) / this._interval) *
					this._interval;
		}
		this._currentId = this._createEvent();
		this._nextTick += this._interval;
		this._nextId = this._createEvent();
	}

	/**
	 * Clean up
	 */
	dispose(): this {
		super.dispose();
		this.transport.clear(this._currentId);
		this.transport.clear(this._nextId);
		this.transport.off("start", this._boundRestart);
		this.transport.off("loopStart", this._boundRestart);
		this.transport.off("ticks", this._boundRestart);
		return this;
	}
}

import { Time, UnitMap, UnitName } from "../type/Units.js";

/**
 * Abstract base class for {@link Param} and {@link Signal}
 */
export abstract class AbstractParam<TypeName extends UnitName> {
	/**
	 * Schedules a parameter value change at the given time.
	 * @param value The value to set the signal.
	 * @param time The time when the change should occur.
	 * @example
	 * return Tone.Offline(() => {
	 * 	const osc = new Tone.Oscillator(20).toDestination().start();
	 * 	// set the frequency to 40 at exactly 0.25 seconds
	 * 	osc.frequency.setValueAtTime(40, 0.25);
	 * }, 0.5, 1);
	 */
	abstract setValueAtTime(value: UnitMap[TypeName], time: Time): this;

	/**
	 * Get the signals value at the given time. Subsequent scheduling
	 * may invalidate the returned value.
	 * @param time When to get the value
	 * @example
	 * const signal = new Tone.Signal().toDestination();
	 * // ramp up to '8' over 3 seconds
	 * signal.rampTo(8, 3);
	 * // ramp back down to '0' over 3 seconds
	 * signal.rampTo(0, 3, "+3");
	 * setInterval(() => {
	 * 	// check the value every 100 ms
	 * 	console.log(signal.getValueAtTime(Tone.now()));
	 * }, 100);
	 */
	abstract getValueAtTime(time: Time): UnitMap[TypeName];

	/**
	 * Creates a schedule point with the current value at the current time.
	 * Automation methods like {@link linearRampToValueAtTime} and {@link exponentialRampToValueAtTime}
	 * require a starting automation value usually set by {@link setValueAtTime}. This method
	 * is useful since it will do a `setValueAtTime` with whatever the currently computed
	 * value at the given time is.
	 * @param time When to add a ramp point.
	 * @example
	 * const osc = new Tone.Oscillator().toDestination().start();
	 * // set the frequency to "G4" in exactly 1 second from now.
	 * osc.frequency.setRampPoint("+1");
	 * osc.frequency.linearRampToValueAtTime("C1", "+2");
	 */
	abstract setRampPoint(time: Time): this;

	/**
	 * Schedules a linear continuous change in parameter value from the
	 * previous scheduled parameter value to the given value.
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(0).toDestination();
	 * 	// the ramp starts from the previously scheduled value
	 * 	signal.setValueAtTime(0, 0.1);
	 * 	signal.linearRampToValueAtTime(1, 0.4);
	 * }, 0.5, 1);
	 */
	abstract linearRampToValueAtTime(
		value: UnitMap[TypeName],
		time: Time
	): this;

	/**
	 * Schedules an exponential continuous change in parameter value from
	 * the previous scheduled parameter value to the given value.
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(1).toDestination();
	 * 	// the ramp starts from the previously scheduled value, which must be positive
	 * 	signal.setValueAtTime(1, 0.1);
	 * 	signal.exponentialRampToValueAtTime(0, 0.4);
	 * }, 0.5, 1);
	 */
	abstract exponentialRampToValueAtTime(
		value: UnitMap[TypeName],
		time: Time
	): this;

	/**
	 * Schedules an exponential continuous change in parameter value from
	 * the current time and current value to the given value over the
	 * duration of the rampTime.
	 * @param value   The value to ramp to.
	 * @param rampTime the time that it takes the
	 *                             value to ramp from its current value
	 * @param startTime When the ramp should start.
	 * @example
	 * const delay = new Tone.FeedbackDelay(0.5, 0.98).toDestination();
	 * // a short burst of noise through the feedback delay
	 * const noise = new Tone.Noise().connect(delay).start().stop("+0.1");
	 * // making the delay time shorter over time will also make the pitch rise
	 * delay.delayTime.exponentialRampTo(0.01, 20);
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(.1).toDestination();
	 * 	signal.exponentialRampTo(5, 0.3, 0.1);
	 * }, 0.5, 1);
	 */
	abstract exponentialRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: Time
	): this;

	/**
	 * Schedules an linear continuous change in parameter value from
	 * the current time and current value to the given value over the
	 * duration of the rampTime.
	 *
	 * @param  value   The value to ramp to.
	 * @param  rampTime the time that it takes the
	 *                              value to ramp from its current value
	 * @param startTime 	When the ramp should start.
	 * @returns {Param} this
	 * @example
	 * const delay = new Tone.FeedbackDelay(0.5, 0.98).toDestination();
	 * // a short burst of noise through the feedback delay
	 * const noise = new Tone.Noise().connect(delay).start().stop("+0.1");
	 * // making the delay time shorter over time will also make the pitch rise
	 * delay.delayTime.linearRampTo(0.01, 20);
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(1).toDestination();
	 * 	signal.linearRampTo(0, 0.3, 0.1);
	 * }, 0.5, 1);
	 */
	abstract linearRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: Time
	): this;

	/**
	 * Start exponentially approaching the target value at the given time. Since it
	 * is an exponential approach it will continue approaching after the ramp duration. The
	 * rampTime is the time that it takes to reach over 99% of the way towards the value.
	 * @param  value   The value to ramp to.
	 * @param  rampTime the time that it takes the
	 *                              value to ramp from its current value
	 * @param startTime 	When the ramp should start.
	 * @example
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(1).toDestination();
	 * 	signal.targetRampTo(0, 0.3, 0.1);
	 * }, 0.5, 1);
	 */
	abstract targetRampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: Time
	): this;

	/**
	 * Start exponentially approaching the target value at the given time. Since it
	 * is an exponential approach it will continue approaching after the ramp duration. The
	 * rampTime is the time that it takes to reach over 99% of the way towards the value. This methods
	 * is similar to setTargetAtTime except the third argument is a time instead of a 'timeConstant'
	 * @param  value   The value to ramp to.
	 * @param time 	When the ramp should start.
	 * @param  rampTime the time that it takes the value to ramp from its current value
	 * @example
	 * const osc = new Tone.Oscillator().toDestination().start();
	 * // exponential approach over 4 seconds starting in 1 second
	 * osc.frequency.exponentialApproachValueAtTime("C4", "+1", 4);
	 */
	abstract exponentialApproachValueAtTime(
		value: UnitMap[TypeName],
		time: Time,
		rampTime: Time
	): this;

	/**
	 * Start exponentially approaching the target value at the given time with
	 * a rate having the given time constant.
	 * @param value
	 * @param startTime
	 * @param timeConstant
	 */
	abstract setTargetAtTime(
		value: UnitMap[TypeName],
		startTime: Time,
		timeConstant: number
	): this;

	/**
	 * Sets an array of arbitrary parameter values starting at the given time
	 * for the given duration.
	 *
	 * @param values
	 * @param startTime
	 * @param duration
	 * @param scaling If the values in the curve should be scaled by some value
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(1).toDestination();
	 * 	signal.setValueCurveAtTime([1, 0.2, 0.8, 0.1, 0], 0.2, 0.3);
	 * }, 0.5, 1);
	 */
	abstract setValueCurveAtTime(
		values: UnitMap[TypeName][],
		startTime: Time,
		duration: Time,
		scaling?: number
	): this;

	/**
	 * Cancels all scheduled parameter changes with times greater than or
	 * equal to startTime.
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(0).toDestination();
	 * 	signal.setValueAtTime(0.1, 0.1);
	 * 	signal.setValueAtTime(0.2, 0.2);
	 * 	signal.setValueAtTime(0.3, 0.3);
	 * 	signal.setValueAtTime(0.4, 0.4);
	 * 	// cancels the last two scheduled changes
	 * 	signal.cancelScheduledValues(0.3);
	 * }, 0.5, 1);
	 */
	abstract cancelScheduledValues(time: Time): this;

	/**
	 * This is similar to {@link cancelScheduledValues} except
	 * it holds the automated value at time until the next automated event.
	 * @example
	 * return Tone.Offline(() => {
	 * 	const signal = new Tone.Signal(0).toDestination();
	 * 	signal.linearRampTo(1, 0.5, 0);
	 * 	signal.cancelAndHoldAtTime(0.3);
	 * }, 0.5, 1);
	 */
	abstract cancelAndHoldAtTime(time: Time): this;

	/**
	 * Ramps to the given value over the duration of the rampTime.
	 * Automatically selects the best ramp type (exponential or linear)
	 * depending on the `units` of the signal
	 *
	 * @param  value
	 * @param  rampTime The time that it takes the value to ramp from its current value
	 * @param startTime When the ramp should start.
	 * @example
	 * const osc = new Tone.Oscillator().toDestination().start();
	 * // schedule it to ramp either linearly or exponentially depending on the units
	 * osc.frequency.rampTo("A2", 10);
	 * @example
	 * const osc = new Tone.Oscillator().toDestination().start();
	 * // schedule it to ramp starting at a specific time
	 * osc.frequency.rampTo("A2", 10, "+2");
	 */
	abstract rampTo(
		value: UnitMap[TypeName],
		rampTime: Time,
		startTime?: Time
	): this;

	/**
	 * The current value of the parameter. Setting this value
	 * is equivalent to setValueAtTime(value, context.currentTime)
	 */
	abstract value: UnitMap[TypeName];

	/**
	 * If the value should be converted or not
	 */
	abstract convert: boolean;

	/**
	 * The unit type
	 */
	abstract readonly units: UnitName;

	/**
	 * True if the signal value is being overridden by
	 * a connected signal. Internal use only.
	 */
	abstract overridden: boolean;

	/**
	 * The minimum value of the output given the units
	 */
	abstract readonly minValue: number;

	/**
	 * The maximum value of the output given the units
	 */
	abstract readonly maxValue: number;
}

import {
	AudioContext as stdAudioContext,
	AudioWorkletNode as stdAudioWorkletNode,
	OfflineAudioContext as stdOfflineAudioContext,
} from "standardized-audio-context";

import { assert } from "../util/Debug.js";
import { isDefined } from "../util/TypeCheck.js";

/**
 * Create a new AudioContext
 */
export function createAudioContext(
	options?: AudioContextOptions
): AudioContext {
	return new stdAudioContext(options) as unknown as AudioContext;
}

/**
 * Create a new OfflineAudioContext
 */
export function createOfflineAudioContext(
	channels: number,
	length: number,
	sampleRate: number
): OfflineAudioContext {
	return new stdOfflineAudioContext(
		channels,
		length,
		sampleRate
	) as unknown as OfflineAudioContext;
}

/**
 * Either the online or offline audio context
 */
export type AnyAudioContext = AudioContext | OfflineAudioContext;

/**
 * Interface for things that Tone.js adds to the window
 */
interface ToneWindow extends Window {
	TONE_SILENCE_LOGGING?: boolean;
	TONE_DEBUG_CLASS?: string;
	BaseAudioContext: any;
	AudioWorkletNode: any;
}

/**
 * A reference to the window object
 * @hidden
 */
export const theWindow: ToneWindow | null =
	typeof self === "object" ? self : null;

/**
 * If the browser has a window object which has an AudioContext
 * @hidden
 */
export const hasAudioContext =
	theWindow &&
	(theWindow.hasOwnProperty("AudioContext") ||
		theWindow.hasOwnProperty("webkitAudioContext"));

export function createAudioWorkletNode(
	context: AnyAudioContext,
	name: string,
	options?: Partial<AudioWorkletNodeOptions>
): AudioWorkletNode {
	assert(
		isDefined(stdAudioWorkletNode),
		"AudioWorkletNode only works in a secure context (https or localhost)"
	);
	return new (
		context instanceof theWindow?.BaseAudioContext
			? theWindow?.AudioWorkletNode
			: stdAudioWorkletNode
	)(context, name, options);
}

/**
 * This promise resolves to a boolean which indicates if the
 * functionality is supported within the currently used browse.
 * Taken from [standardized-audio-context](https://github.com/chrisguttandin/standardized-audio-context#issupported)
 */
export { isSupported as supported } from "standardized-audio-context";

import type { TransportInstance as Transport } from "../clock/Transport.js";
import { Seconds } from "../type/Units.js";
import type { DrawInstance as Draw } from "../util/Draw.js";
import { Emitter } from "../util/Emitter.js";
import { AnyAudioContext } from "./AudioContext.js";
import type { DestinationInstance as Destination } from "./Destination.js";
import type { ListenerInstance as Listener } from "./Listener.js";

// these are either not used in Tone.js or deprecated and not implemented.
export type ExcludedFromBaseAudioContext =
	| "onstatechange"
	| "addEventListener"
	| "removeEventListener"
	| "listener"
	| "dispatchEvent"
	| "audioWorklet"
	| "destination"
	| "createScriptProcessor";

// the subset of the BaseAudioContext which Tone.Context implements.
export type BaseAudioContextSubset = Omit<
	BaseAudioContext,
	ExcludedFromBaseAudioContext
>;

export type ContextLatencyHint = AudioContextLatencyCategory;

/**
 * Shared class for both Offline and Online Audio Context's
 */
export abstract class BaseContext
	extends Emitter<"statechange" | "tick">
	implements BaseAudioContextSubset
{
	//---------------------------
	// BASE AUDIO CONTEXT METHODS
	//---------------------------
	abstract createAnalyser(): AnalyserNode;

	abstract createOscillator(): OscillatorNode;

	abstract createBufferSource(): AudioBufferSourceNode;

	abstract createBiquadFilter(): BiquadFilterNode;

	abstract createBuffer(
		_numberOfChannels: number,
		_length: number,
		_sampleRate: number
	): AudioBuffer;

	abstract createChannelMerger(
		_numberOfInputs?: number | undefined
	): ChannelMergerNode;

	abstract createChannelSplitter(
		_numberOfOutputs?: number | undefined
	): ChannelSplitterNode;

	abstract createConstantSource(): ConstantSourceNode;

	abstract createConvolver(): ConvolverNode;

	abstract createDelay(_maxDelayTime?: number | undefined): DelayNode;

	abstract createDynamicsCompressor(): DynamicsCompressorNode;

	abstract createGain(): GainNode;

	abstract createIIRFilter(
		_feedForward: number[] | Float32Array,
		_feedback: number[] | Float32Array
	): IIRFilterNode;

	abstract createPanner(): PannerNode;

	abstract createPeriodicWave(
		_real: number[] | Float32Array,
		_imag: number[] | Float32Array,
		_constraints?: PeriodicWaveConstraints | undefined
	): PeriodicWave;

	abstract createStereoPanner(): StereoPannerNode;

	abstract createWaveShaper(): WaveShaperNode;

	abstract createMediaStreamSource(
		_stream: MediaStream
	): MediaStreamAudioSourceNode;

	abstract createMediaElementSource(
		_element: HTMLMediaElement
	): MediaElementAudioSourceNode;

	abstract createMediaStreamDestination(): MediaStreamAudioDestinationNode;

	abstract decodeAudioData(_audioData: ArrayBuffer): Promise<AudioBuffer>;

	//---------------------------
	// TONE AUDIO CONTEXT METHODS
	//---------------------------

	abstract createAudioWorkletNode(
		_name: string,
		_options?: Partial<AudioWorkletNodeOptions>
	): AudioWorkletNode;

	abstract get rawContext(): AnyAudioContext;

	abstract addAudioWorkletModule(_url: string): Promise<void>;

	abstract lookAhead: number;

	abstract latencyHint: ContextLatencyHint | Seconds;

	abstract resume(): Promise<void>;

	abstract setTimeout(
		_fn: (...args: any[]) => void,
		_timeout: Seconds
	): number;

	abstract clearTimeout(_id: number): this;

	abstract setInterval(
		_fn: (...args: any[]) => void,
		_interval: Seconds
	): number;

	abstract clearInterval(_id: number): this;

	/**
	 * @deprecated use ToneConstantSource instead
	 */
	abstract getConstant(_val: number): AudioBufferSourceNode;

	abstract get currentTime(): Seconds;

	abstract get state(): AudioContextState;

	abstract get sampleRate(): number;

	abstract get listener(): Listener;

	abstract get transport(): Transport;

	abstract get draw(): Draw;

	abstract get destination(): Destination;

	abstract now(): Seconds;

	abstract immediate(): Seconds;

	/*
	 * This is a placeholder so that JSON.stringify does not throw an error
	 * This matches what JSON.stringify(audioContext) returns on a native
	 * audioContext instance.
	 */
	toJSON(): Record<string, any> {
		return {};
	}

	readonly isOffline: boolean = false;
}

import { expect } from "chai";

import { ConstantOutput } from "../../../test/helper/ConstantOutput.js";
import { Offline } from "../../../test/helper/Offline.js";
import { TransportInstance } from "../clock/Transport.js";
import { getContext } from "../Global.js";
import { DrawInstance } from "../util/Draw.js";
import { createAudioContext } from "./AudioContext.js";
import { Context } from "./Context.js";
import { DestinationInstance } from "./Destination.js";
import { ListenerInstance } from "./Listener.js";
import { connect } from "./ToneAudioNode.js";

describe("Context", () => {
	it("creates and disposes the classes attached to the context", async () => {
		const ac = createAudioContext();
		const context = new Context(ac);
		const ctxDest = context.destination;
		const ctxDraw = context.draw;
		const ctxTransport = context.transport;
		const ctxListener = context.listener;
		expect(context.destination).is.instanceOf(DestinationInstance);
		expect(context.draw).is.instanceOf(DrawInstance);
		expect(context.listener).is.instanceOf(ListenerInstance);
		await context.close();
		expect(ctxDest.disposed).to.be.true;
		expect(ctxDraw.disposed).to.be.true;
		expect(ctxTransport.disposed).to.be.true;
		expect(ctxListener.disposed).to.be.true;
		context.dispose();
	});

	context("AudioContext", () => {
		it("extends the AudioContext methods", () => {
			const ctx = new Context(createAudioContext());
			expect(ctx).to.have.property("createGain");
			expect(ctx.createGain()).to.have.property("gain");
			expect(ctx).to.have.property("createOscillator");
			expect(ctx.createOscillator()).to.be.have.property("frequency");
			expect(ctx).to.have.property("createDelay");
			expect(ctx.createDelay()).to.be.have.property("delayTime");
			expect(ctx).to.have.property("createConstantSource");
			ctx.dispose();
			return ctx.close();
		});

		it("can be stringified", () => {
			const ctx = new Context(createAudioContext());
			expect(JSON.stringify(ctx)).to.equal("{}");
			ctx.dispose();
			return ctx.close();
		});

		it("clock is running", (done) => {
			const interval = setInterval(() => {
				if (getContext().currentTime > 0.5) {
					clearInterval(interval);
					done();
				}
			}, 20);
		});

		it("has a rawContext", () => {
			const ctx = new Context(createAudioContext());
			expect(ctx.rawContext).has.property("destination");
			expect(ctx.rawContext).has.property("sampleRate");
			ctx.dispose();
			return ctx.close();
		});

		it("can be constructed with an options object", () => {
			const ctx = new Context({
				clockSource: "timeout",
				latencyHint: "playback",
				lookAhead: 0.2,
				updateInterval: 0.1,
				sampleRate: 32000,
			});
			expect(ctx.lookAhead).to.equal(0.2);
			expect(ctx.updateInterval).to.equal(0.1);
			expect(ctx.latencyHint).to.equal("playback");
			expect(ctx.clockSource).to.equal("timeout");
			expect(ctx.sampleRate).to.equal(32000);
			ctx.dispose();
			return ctx.close();
		});

		it("returns 'now' and 'immediate' time", () => {
			const ctx = new Context();
			expect(ctx.now()).to.be.a("number");
			expect(ctx.immediate()).to.be.a("number");
			ctx.dispose();
			return ctx.close();
		});
	});

	context("state", () => {
		it("can suspend and resume the state", async () => {
			const ac = createAudioContext();
			const context = new Context(ac);
			expect(context.rawContext).to.equal(ac);
			await ac.suspend();
			expect(context.state).to.equal("suspended");
			await context.resume();
			expect(context.state).to.equal("running");
			context.dispose();
			return context.close();
		});

		it("invokes the statechange event", async () => {
			const ac = createAudioContext();
			const context = new Context(ac);
			let triggerChange = false;
			context.on("statechange", (state) => {
				if (!triggerChange) {
					triggerChange = true;
					expect(state).to.equal("running");
				}
			});
			await context.resume();
			await new Promise<void>((done) => setTimeout(() => done(), 10));
			expect(triggerChange).to.equal(true);
			return context.dispose();
		});
	});

	context("clockSource", () => {
		let ctx;
		beforeEach(() => {
			ctx = new Context();
			return ctx.resume();
		});

		afterEach(() => {
			ctx.dispose();
			return ctx.close();
		});

		it("defaults to 'worker'", () => {
			expect(ctx.clockSource).to.equal("worker");
		});

		it("provides callback", (done) => {
			expect(ctx.clockSource).to.equal("worker");
			ctx.setTimeout(() => {
				done();
			}, 0.1);
		});

		it("can be set to 'timeout'", (done) => {
			ctx.clockSource = "timeout";
			expect(ctx.clockSource).to.equal("timeout");
			ctx.setTimeout(() => {
				done();
			}, 0.1);
		});

		it("can be set to 'offline'", (done) => {
			ctx.clockSource = "offline";
			expect(ctx.clockSource).to.equal("offline");
			// provides no callback
			ctx.setTimeout(() => {
				throw new Error("shouldn't be called");
			}, 0.1);
			setTimeout(() => {
				done();
			}, 200);
		});
	});
	context("setTimeout", () => {
		let ctx;
		beforeEach(() => {
			ctx = new Context();
			return ctx.resume();
		});

		afterEach(() => {
			ctx.dispose();
			return ctx.close();
		});

		it("can set a timeout", (done) => {
			ctx.setTimeout(() => {
				done();
			}, 0.1);
		});

		it("returns an id", () => {
			expect(ctx.setTimeout(() => {}, 0.1)).to.be.a("number");
			// try clearing a random ID, shouldn't cause any errors
			ctx.clearTimeout(-2);
		});

		it("timeout is not invoked when cancelled", (done) => {
			const id = ctx.setTimeout(() => {
				throw new Error("shouldn't be invoked");
			}, 0.01);
			ctx.clearTimeout(id);
			ctx.setTimeout(() => {
				done();
			}, 0.02);
		});

		it("order is maintained", (done) => {
			let wasInvoked = false;
			ctx.setTimeout(() => {
				expect(wasInvoked).to.equal(true);
				done();
			}, 0.02);
			ctx.setTimeout(() => {
				wasInvoked = true;
			}, 0.01);
		});

		it("is invoked in the offline context", () => {
			return Offline((context) => {
				const transport = new TransportInstance({ context });
				transport.context.setTimeout(() => {
					expect(transport.now()).to.be.closeTo(0.01, 0.005);
				}, 0.01);
			}, 0.05);
		});

		it("can efficiently add and remove 10k timeouts", () => {
			const ids: number[] = [];
			for (let i = 0; i < 10_000; i++) {
				ids.push(ctx.setTimeout(() => {}, i * 0.001));
			}
			for (const id of ids) {
				ctx.clearTimeout(id);
			}
		}).timeout(100);

		it("is robust against altering the timeline within the callback fn", (done) => {
			let invokeCount = 0;
			function checkDone(id: number) {
				// clearing the current event alters the timeline and should not cause an issue
				ctx.clearTimeout(id);
				invokeCount++;
				if (invokeCount === 3) {
					done();
				}
			}
			const id0 = ctx.setTimeout(() => checkDone(id0), 0.01);
			const id1 = ctx.setTimeout(() => checkDone(id1), 0.01);
			const id2 = ctx.setTimeout(() => checkDone(id2), 0.01);
		});
	});

	context("setInterval", () => {
		let ctx;
		beforeEach(() => {
			ctx = new Context();
			return ctx.resume();
		});

		afterEach(() => {
			ctx.dispose();
			return ctx.close();
		});

		it("can set an interval", (done) => {
			ctx.setInterval(() => {
				done();
			}, 0.1);
		});

		it("returns an id", () => {
			expect(ctx.setInterval(() => {}, 0.1)).to.be.a("number");
			// try clearing a random ID, shouldn't cause any errors
			ctx.clearInterval(-2);
		});

		it("timeout is not invoked when cancelled", (done) => {
			const id = ctx.setInterval(() => {
				throw new Error("shouldn't be invoked");
			}, 0.01);
			ctx.clearInterval(id);
			ctx.setInterval(() => {
				done();
			}, 0.02);
		});

		it("order is maintained", (done) => {
			let wasInvoked = false;
			ctx.setInterval(() => {
				expect(wasInvoked).to.equal(true);
				done();
			}, 0.02);
			ctx.setInterval(() => {
				wasInvoked = true;
			}, 0.01);
		});

		it("is invoked in the offline context", async () => {
			let invocationCount = 0;
			await Offline((context) => {
				context.setInterval(() => {
					invocationCount++;
				}, 0.01);
			}, 0.051);
			expect(invocationCount).to.equal(4);
		});

		it("is invoked with the right interval", async () => {
			let numberOfInvocations = 0;
			await Offline((context) => {
				let intervalTime = context.now();
				context.setInterval(() => {
					expect(context.now() - intervalTime).to.be.closeTo(
						0.01,
						0.005
					);
					intervalTime = context.now();
					numberOfInvocations++;
				}, 0.01);
			}, 0.051);
			expect(numberOfInvocations).to.equal(4);
		});
	});

	context("get/set", () => {
		let ctx;
		beforeEach(() => {
			ctx = new Context();
			return ctx.resume();
		});

		afterEach(() => {
			ctx.dispose();
			return ctx.close();
		});

		it("can set the lookAhead", () => {
			ctx.lookAhead = 0.05;
			expect(ctx.lookAhead).to.equal(0.05);
		});

		it("can set the updateInterval", () => {
			ctx.updateInterval = 0.05;
			expect(ctx.updateInterval).to.equal(0.05);
		});

		it("gets a constant signal", () => {
			return ConstantOutput((context) => {
				const bufferSrc = context.getConstant(1);
				connect(bufferSrc, context.destination);
			}, 1);
		});

		it("multiple calls return the same buffer source", () => {
			const bufferA = ctx.getConstant(2);
			const bufferB = ctx.getConstant(2);
			expect(bufferA).to.equal(bufferB);
		});
	});

	context("Methods", () => {
		let ctx;
		beforeEach(() => {
			ctx = new Context();
			return ctx.resume();
		});

		afterEach(() => {
			ctx.dispose();
			return ctx.close();
		});

		it("can create a MediaElementAudioSourceNode", () => {
			const audioNode = document.createElement("audio");
			const node = ctx.createMediaElementSource(audioNode);
			expect(node).is.not.undefined;
		});
	});
});

import { Ticker, TickerClockSource } from "../clock/Ticker.js";
import type { TransportInstance as Transport } from "../clock/Transport.js";
import { Seconds } from "../type/Units.js";
import { isAudioContext } from "../util/AdvancedTypeCheck.js";
import { assert } from "../util/Debug.js";
import { optionsFromArguments } from "../util/Defaults.js";
import type { DrawInstance as Draw } from "../util/Draw.js";
import { Timeline } from "../util/Timeline.js";
import { isDefined } from "../util/TypeCheck.js";
import {
	AnyAudioContext,
	createAudioContext,
	createAudioWorkletNode,
} from "./AudioContext.js";
import { BaseContext, ContextLatencyHint } from "./BaseContext.js";
import { closeContext, initializeContext } from "./ContextInitialization.js";
import type { DestinationInstance as Destination } from "./Destination.js";
import type { ListenerInstance as Listener } from "./Listener.js";

export interface ContextOptions {
	clockSource: TickerClockSource;
	latencyHint: ContextLatencyHint;
	lookAhead: Seconds;
	updateInterval: Seconds;
	context: AnyAudioContext;
	sampleRate: number;
}

export interface ContextTimeoutEvent {
	callback: (...args: any[]) => void;
	id: number;
	time: Seconds;
}

/**
 * Wraps the native AudioContext.
 * @category Core
 */
export class Context extends BaseContext {
	readonly name: string = "Context";

	/**
	 * A private reference to the BaseAudioContext.
	 */
	protected readonly _context: AnyAudioContext;

	/**
	 * A reliable callback method.
	 */
	private readonly _ticker: Ticker;

	/**
	 * The default latency hint.
	 */
	private _latencyHint!: ContextLatencyHint | Seconds;

	/**
	 * An object containing all of the AudioBufferSourceNodes with constant values.
	 */
	private _constants = new Map<number, AudioBufferSourceNode>();

	/**
	 * All of the setTimeout events.
	 */
	private _timeouts: Timeline<ContextTimeoutEvent> = new Timeline();

	/**
	 * A Map from timeout ID to event for O(1) lookup in clearTimeout.
	 */
	private _timeoutMap = new Map<number, ContextTimeoutEvent>();

	/**
	 * The timeout id counter
	 */
	private _timeoutIds = 0;

	/**
	 * A reference the Transport singleton belonging to this context
	 */
	private _transport!: Transport;

	/**
	 * A reference the Listener singleton belonging to this context
	 */
	private _listener!: Listener;

	/**
	 * A reference the Destination singleton belonging to this context
	 */
	private _destination!: Destination;

	/**
	 * A reference the Transport singleton belonging to this context
	 */
	private _draw!: Draw;

	/**
	 * Private indicator if the context has been initialized
	 */
	private _initialized = false;

	/**
	 * Private indicator if a close() has been called on the context, since close is async
	 */
	private _closeStarted = false;

	/**
	 * Indicates if the context is an OfflineAudioContext or an AudioContext
	 */
	readonly isOffline: boolean = false;

	constructor(context?: AnyAudioContext);
	constructor(options?: Partial<ContextOptions>);
	constructor() {
		super();
		const options = optionsFromArguments(Context.getDefaults(), arguments, [
			"context",
		]);

		if (options.context) {
			this._context = options.context;
			// custom context provided, latencyHint unknown (unless explicitly provided in options)
			this._latencyHint = arguments[0]?.latencyHint || "";
		} else {
			this._context = createAudioContext(
				options.sampleRate
					? {
							latencyHint: options.latencyHint,
							sampleRate: options.sampleRate,
						}
					: {
							latencyHint: options.latencyHint,
						}
			);
			this._latencyHint = options.latencyHint;
		}

		this._ticker = new Ticker(
			this.emit.bind(this, "tick"),
			options.clockSource,
			options.updateInterval,
			this._context.sampleRate
		);
		this.on("tick", this._timeoutLoop.bind(this));

		// fwd events from the context
		this._context.onstatechange = () => {
			this.emit("statechange", this.state);
		};

		// if no custom updateInterval provided, updateInterval will be derived by lookAhead setter
		this[
			arguments[0]?.hasOwnProperty("updateInterval")
				? "_lookAhead"
				: "lookAhead"
		] = options.lookAhead;
	}

	static getDefaults(): ContextOptions {
		return {
			clockSource: "worker",
			latencyHint: "interactive",
			lookAhead: 0.1,
			updateInterval: 0.05,
		} as ContextOptions;
	}

	/**
	 * Finish setting up the context. **You usually do not need to do this manually.**
	 */
	private initialize(): this {
		if (!this._initialized) {
			// add any additional modules
			initializeContext(this);
			this._initialized = true;
		}
		return this;
	}

	//---------------------------
	// BASE AUDIO CONTEXT METHODS
	//---------------------------

	createAnalyser(): AnalyserNode {
		return this._context.createAnalyser();
	}
	createOscillator(): OscillatorNode {
		return this._context.createOscillator();
	}
	createBufferSource(): AudioBufferSourceNode {
		return this._context.createBufferSource();
	}
	createBiquadFilter(): BiquadFilterNode {
		return this._context.createBiquadFilter();
	}
	createBuffer(
		numberOfChannels: number,
		length: number,
		sampleRate: number
	): AudioBuffer {
		return this._context.createBuffer(numberOfChannels, length, sampleRate);
	}
	createChannelMerger(
		numberOfInputs?: number | undefined
	): ChannelMergerNode {
		return this._context.createChannelMerger(numberOfInputs);
	}
	createChannelSplitter(
		numberOfOutputs?: number | undefined
	): ChannelSplitterNode {
		return this._context.createChannelSplitter(numberOfOutputs);
	}
	createConstantSource(): ConstantSourceNode {
		return this._context.createConstantSource();
	}
	createConvolver(): ConvolverNode {
		return this._context.createConvolver();
	}
	createDelay(maxDelayTime?: number | undefined): DelayNode {
		return this._context.createDelay(maxDelayTime);
	}
	createDynamicsCompressor(): DynamicsCompressorNode {
		return this._context.createDynamicsCompressor();
	}
	createGain(): GainNode {
		return this._context.createGain();
	}
	createIIRFilter(
		feedForward: number[] | Float32Array,
		feedback: number[] | Float32Array
	): IIRFilterNode {
		// @ts-ignore
		return this._context.createIIRFilter(feedForward, feedback);
	}
	createPanner(): PannerNode {
		return this._context.createPanner();
	}
	createPeriodicWave(
		real: number[] | Float32Array,
		imag: number[] | Float32Array,
		constraints?: PeriodicWaveConstraints | undefined
	): PeriodicWave {
		return this._context.createPeriodicWave(real, imag, constraints);
	}
	createStereoPanner(): StereoPannerNode {
		return this._context.createStereoPanner();
	}
	createWaveShaper(): WaveShaperNode {
		return this._context.createWaveShaper();
	}
	createMediaStreamSource(stream: MediaStream): MediaStreamAudioSourceNode {
		assert(
			isAudioContext(this._context),
			"Not available if OfflineAudioContext"
		);
		const context = this._context as AudioContext;
		return context.createMediaStreamSource(stream);
	}
	createMediaElementSource(
		element: HTMLMediaElement
	): MediaElementAudioSourceNode {
		assert(
			isAudioContext(this._context),
			"Not available if OfflineAudioContext"
		);
		const context = this._context as AudioContext;
		return context.createMediaElementSource(element);
	}
	createMediaStreamDestination(): MediaStreamAudioDestinationNode {
		assert(
			isAudioContext(this._context),
			"Not available if OfflineAudioContext"
		);
		const context = this._context as AudioContext;
		return context.createMediaStreamDestination();
	}
	decodeAudioData(audioData: ArrayBuffer): Promise<AudioBuffer> {
		return this._context.decodeAudioData(audioData);
	}

	/**
	 * The current time in seconds of the AudioContext.
	 */
	get currentTime(): Seconds {
		return this._context.currentTime;
	}
	/**
	 * The current time in seconds of the AudioContext.
	 */
	get state(): AudioContextState {
		return this._context.state;
	}
	/**
	 * The current time in seconds of the AudioContext.
	 */
	get sampleRate(): number {
		return this._context.sampleRate;
	}

	/**
	 * The listener
	 */
	get listener(): Listener {
		this.initialize();
		return this._listener;
	}
	set listener(l) {
		assert(
			!this._initialized,
			"The listener cannot be set after initialization."
		);
		this._listener = l;
	}

	/**
	 * There is only one Transport per Context. It is created on initialization.
	 */
	get transport(): Transport {
		this.initialize();
		return this._transport;
	}
	set transport(t: Transport) {
		assert(
			!this._initialized,
			"The transport cannot be set after initialization."
		);
		this._transport = t;
	}

	/**
	 * This is the Draw object for the context which is useful for synchronizing the draw frame with the Tone.js clock.
	 */
	get draw(): Draw {
		this.initialize();
		return this._draw;
	}
	set draw(d) {
		assert(!this._initialized, "Draw cannot be set after initialization.");
		this._draw = d;
	}

	/**
	 * A reference to the Context's destination node.
	 */
	get destination(): Destination {
		this.initialize();
		return this._destination;
	}
	set destination(d: Destination) {
		assert(
			!this._initialized,
			"The destination cannot be set after initialization."
		);
		this._destination = d;
	}

	//--------------------------------------------
	// AUDIO WORKLET
	//--------------------------------------------

	/**
	 * A set of unsettled promises returned by the addModule method
	 */
	private _workletPromises = new Set<Promise<void>>();

	/**
	 * Create an audio worklet node from a name and options. The module
	 * must first be loaded using {@link addAudioWorkletModule}.
	 */
	createAudioWorkletNode(
		name: string,
		options?: Partial<AudioWorkletNodeOptions>
	): AudioWorkletNode {
		return createAudioWorkletNode(this.rawContext, name, options);
	}

	/**
	 * Add an AudioWorkletProcessor module
	 * @param url The url of the module
	 */
	async addAudioWorkletModule(url: string): Promise<void> {
		assert(
			isDefined(this.rawContext.audioWorklet),
			"AudioWorkletNode is only available in a secure context (https or localhost)"
		);
		const workletPromise = this.rawContext.audioWorklet.addModule(url);

		this._workletPromises.add(workletPromise);
		workletPromise.finally(() =>
			this._workletPromises.delete(workletPromise)
		);

		return workletPromise;
	}

	/**
	 * Returns a promise which resolves when all of the worklets have been loaded on this context
	 */
	protected async workletsAreReady(): Promise<void> {
		await Promise.all(this._workletPromises);
	}

	//---------------------------
	// TICKER
	//---------------------------

	/**
	 * How often the interval callback is invoked.
	 * This number corresponds to how responsive the scheduling
	 * can be. Setting to 0 will result in the lowest practical interval
	 * based on context properties. context.updateInterval + context.lookAhead
	 * gives you the total latency between scheduling an event and hearing it.
	 */
	get updateInterval(): Seconds {
		return this._ticker.updateInterval;
	}
	set updateInterval(interval: Seconds) {
		this._ticker.updateInterval = interval;
	}

	/**
	 * What the source of the clock is, either "worker" (default),
	 * "timeout", or "offline" (none).
	 */
	get clockSource(): TickerClockSource {
		return this._ticker.type;
	}
	set clockSource(type: TickerClockSource) {
		this._ticker.type = type;
	}

	/**
	 * The amount of time into the future events are scheduled. Giving Web Audio
	 * a short amount of time into the future to schedule events can reduce clicks and
	 * improve performance. This value can be set to 0 to get the lowest latency.
	 * Adjusting this value also affects the {@link updateInterval}.
	 */
	get lookAhead(): Seconds {
		return this._lookAhead;
	}
	set lookAhead(time: Seconds) {
		this._lookAhead = time;
		// if lookAhead is 0, default to .01 updateInterval
		this.updateInterval = time ? time / 2 : 0.01;
	}
	private _lookAhead!: Seconds;

	/**
	 * The type of playback, which affects tradeoffs between audio
	 * output latency and responsiveness.
	 * In addition to setting the value in seconds, the latencyHint also
	 * accepts the strings "interactive" (prioritizes low latency),
	 * "playback" (prioritizes sustained playback), "balanced" (balances
	 * latency and performance).
	 * @example
	 * // prioritize sustained playback
	 * const context = new Tone.Context({ latencyHint: "playback" });
	 * // set this context as the global Context
	 * Tone.setContext(context);
	 * // the global context is gettable with Tone.getContext()
	 * console.log(Tone.getContext().latencyHint);
	 */
	get latencyHint(): ContextLatencyHint | Seconds {
		return this._latencyHint;
	}

	/**
	 * The unwrapped AudioContext or OfflineAudioContext
	 */
	get rawContext(): AnyAudioContext {
		return this._context;
	}

	/**
	 * The current audio context time plus a short {@link lookAhead}.
	 * @example
	 * setInterval(() => {
	 * 	console.log("now", Tone.now());
	 * }, 100);
	 */
	now(): Seconds {
		return this._context.currentTime + this._lookAhead;
	}

	/**
	 * The current audio context time without the {@link lookAhead}.
	 * In most cases it is better to use {@link now} instead of {@link immediate} since
	 * with {@link now} the {@link lookAhead} is applied equally to _all_ components including internal components,
	 * to making sure that everything is scheduled in sync. Mixing {@link now} and {@link immediate}
	 * can cause some timing issues. If no lookAhead is desired, you can set the {@link lookAhead} to `0`.
	 */
	immediate(): Seconds {
		return this._context.currentTime;
	}

	/**
	 * Starts the audio context from a suspended state. This is required
	 * to initially start the AudioContext.
	 * @see {@link start}
	 */
	resume(): Promise<void> {
		if (isAudioContext(this._context)) {
			return this._context.resume();
		} else {
			return Promise.resolve();
		}
	}

	/**
	 * Close the context. Once closed, the context can no longer be used and
	 * any AudioNodes created from the context will be silent.
	 */
	async close(): Promise<void> {
		if (
			isAudioContext(this._context) &&
			this.state !== "closed" &&
			!this._closeStarted
		) {
			this._closeStarted = true;
			await this._context.close();
		}
		if (this._initialized) {
			closeContext(this);
		}
	}

	/**
	 * **Internal** Generate a looped buffer at some constant value.
	 * @deprecated
	 */
	getConstant(val: number): AudioBufferSourceNode {
		if (this._constants.has(val)) {
			return this._constants.get(val) as AudioBufferSourceNode;
		} else {
			const buffer = this._context.createBuffer(
				1,
				128,
				this._context.sampleRate
			);
			const arr = buffer.getChannelData(0);
			for (let i = 0; i < arr.length; i++) {
				arr[i] = val;
			}
			const constant = this._context.createBufferSource();
			constant.channelCount = 1;
			constant.channelCountMode = "explicit";
			constant.buffer = buffer;
			constant.loop = true;
			constant.start(0);
			this._constants.set(val, constant);
			return constant;
		}
	}

	/**
	 * Clean up. Also closes the audio context.
	 */
	dispose(): this {
		super.dispose();
		this._ticker.dispose();
		this._timeouts.dispose();
		this._timeoutMap.clear();
		Object.keys(this._constants).map((val) =>
			this._constants[val].disconnect()
		);
		this.close();
		return this;
	}

	//---------------------------
	// TIMEOUTS
	//---------------------------

	/**
	 * Add a timeout event to the timeline and map.
	 */
	private _addTimeoutEvent(event: ContextTimeoutEvent): void {
		this._timeouts.add(event);
		this._timeoutMap.set(event.id, event);
	}

	/**
	 * Remove a timeout event from the timeline and map.
	 */
	private _removeTimeoutEvent(event: ContextTimeoutEvent): void {
		this._timeouts.remove(event);
		// Skips the map deletion in setInterval case where the same id
		// is reused for the next event.
		if (this._timeoutMap.get(event.id) === event) {
			this._timeoutMap.delete(event.id);
		}
	}

	/**
	 * The private loop which keeps track of the context scheduled timeouts
	 * Is invoked from the clock source
	 */
	private _timeoutLoop(): void {
		const now = this.now();
		this._timeouts.forEachBefore(now, (event) => {
			try {
				event.callback();
			} finally {
				this._removeTimeoutEvent(event);
			}
		});
	}

	/**
	 * A `setTimeout` which is guaranteed by the clock source.
	 *
	 * Also runs in the offline context.
	 *
	 * @param fn The callback to invoke.
	 * @param timeout The timeout in seconds.
	 * @returns ID to use when invoking {@link clearTimeout}.
	 */
	setTimeout(fn: (...args: any[]) => void, timeout: Seconds): number {
		this._timeoutIds++;
		const now = this.now();
		this._addTimeoutEvent({
			callback: fn,
			id: this._timeoutIds,
			time: now + timeout,
		});
		return this._timeoutIds;
	}

	/**
	 * Clears a previously scheduled timeout with {@link setTimeout}.
	 * @param id The ID returned from {@link setTimeout}.
	 */
	clearTimeout(id: number): this {
		const event = this._timeoutMap.get(id);
		if (event) {
			this._removeTimeoutEvent(event);
		}
		return this;
	}

	/**
	 * Clear the function scheduled by {@link setInterval}.
	 * @param id The ID returned from {@link setInterval}.
	 */
	clearInterval(id: number): this {
		return this.clearTimeout(id);
	}

	/**
	 * Adds a repeating event to the context's callback clock.
	 * @param fn The callback to invoke.
	 * @param interval The timeout in seconds.
	 * @returns ID to use when invoking {@link clearInterval}.
	 */
	setInterval(fn: (...args: any[]) => void, interval: Seconds): number {
		const id = ++this._timeoutIds;
		const intervalFn = () => {
			const now = this.now();
			this._addTimeoutEvent({
				callback: () => {
					// invoke the callback
					fn();
					// invoke the event to repeat it
					intervalFn();
				},
				id,
				time: now + interval,
			});
		};
		// kick it off
		intervalFn();
		return id;
	}
}

//-------------------------------------
// INITIALIZING NEW CONTEXT
//-------------------------------------
import type { Context } from "./Context.js";

/**
 * Array of callbacks to invoke when a new context is created
 */
const notifyNewContext: Array<(ctx: Context) => void> = [];

/**
 * Used internally to setup a new Context
 */
export function onContextInit(cb: (ctx: Context) => void): void {
	notifyNewContext.push(cb);
}

/**
 * Invoke any classes which need to also be initialized when a new context is created.
 */
export function initializeContext(ctx: Context): void {
	// add any additional modules
	notifyNewContext.forEach((cb) => cb(ctx));
}

/**
 * Array of callbacks to invoke when a new context is closed
 */
const notifyCloseContext: Array<(ctx: Context) => void> = [];

/**
 * Used internally to tear down a Context
 */
export function onContextClose(cb: (ctx: Context) => void): void {
	notifyCloseContext.push(cb);
}

export function closeContext(ctx: Context): void {
	// remove any additional modules
	notifyCloseContext.forEach((cb) => cb(ctx));
}

import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { connectFrom, connectTo } from "../../../test/helper/Connect.js";
import { PassAudio } from "../../../test/helper/PassAudio.js";
import { connect } from "../context/ToneAudioNode.js";
import { Delay } from "./Delay.js";

describe("Delay", () => {
	BasicTests(Delay);

	it("can be created and disposed", () => {
		const delay = new Delay();
		delay.dispose();
	});

	it("handles input and output connections", () => {
		const delay = new Delay();
		delay.connect(connectTo());
		connectFrom().connect(delay);
		connectFrom().connect(delay.delayTime);
		delay.dispose();
	});

	it("can be constructed with an options object", () => {
		const delay = new Delay({
			delayTime: 0.3,
			maxDelay: 2,
		});
		expect(delay.delayTime.value).to.be.closeTo(0.3, 0.001);
		expect(delay.maxDelay).to.equal(2);
		delay.dispose();
	});

	it("if the constructor delay time is greater than maxDelay, use that as the maxDelay time", () => {
		const delay = new Delay(3);
		expect(delay.delayTime.value).to.be.closeTo(3, 0.001);
		delay.dispose();
	});

	it("clamps the delayTime range between 0 and maxDelay", () => {
		const delay = new Delay({
			maxDelay: 1,
		});
		expect(() => {
			delay.delayTime.value = 2;
		}).to.throw(RangeError);
		expect(() => {
			delay.delayTime.value = -1;
		}).to.throw(RangeError);
		expect(delay.delayTime.value).to.be.closeTo(0, 0.001);
		delay.dispose();
	});

	it("can set the delayTime value", () => {
		const delay = new Delay();
		expect(delay.delayTime.value).to.be.closeTo(0, 0.001);
		delay.delayTime.value = 0.2;
		expect(delay.delayTime.value).to.be.closeTo(0.2, 0.001);
		delay.dispose();
	});

	it("can be constructed with options object", () => {
		const delay = new Delay({
			delayTime: 0.4,
		});
		expect(delay.delayTime.value).to.be.closeTo(0.4, 0.001);
		delay.dispose();
	});

	it("can be constructed with an initial value", () => {
		const delay = new Delay(0.3);
		expect(delay.delayTime.value).to.be.closeTo(0.3, 0.001);
		delay.dispose();
	});

	it("can set the units", () => {
		const delay = new Delay(0);
		expect(delay.delayTime.value).to.be.closeTo(0, 0.001);
		delay.dispose();
	});

	it("can get the value using 'get'", () => {
		const delay = new Delay(2);
		const value = delay.get();
		expect(value.delayTime).to.be.closeTo(2, 0.001);
		delay.dispose();
	});

	it("can set the value using 'set'", () => {
		const delay = new Delay(5);
		delay.set({
			delayTime: 4,
		});
		expect(delay.delayTime.value).to.be.closeTo(4, 0.001);
		delay.dispose();
	});

	it("passes audio through", () => {
		return PassAudio((input) => {
			const delay = new Delay().toDestination();
			connect(input, delay);
		});
	});
});

import { Param } from "../context/Param.js";
import { Seconds, Time } from "../type/Units.js";
import { optionsFromArguments } from "../util/Defaults.js";
import { readOnly } from "../util/Interface.js";
import { ToneAudioNode, ToneAudioNodeOptions } from "./ToneAudioNode.js";

export interface DelayOptions extends ToneAudioNodeOptions {
	delayTime: Time;
	maxDelay: Time;
}

/**
 * Wrapper around Web Audio's native [DelayNode](http://webaudio.github.io/web-audio-api/#the-delaynode-interface).
 * @category Core
 * @example
 * return Tone.Offline(() => {
 * 	const delay = new Tone.Delay(0.1).toDestination();
 * 	// connect the signal to both the delay and the destination
 * 	const pulse = new Tone.PulseOscillator().connect(delay).toDestination();
 * 	// start and stop the pulse
 * 	pulse.start(0).stop(0.01);
 * }, 0.5, 1);
 */
export class Delay extends ToneAudioNode<DelayOptions> {
	readonly name: string = "Delay";

	/**
	 * Private holder of the max delay time
	 */
	private _maxDelay: Seconds;

	/**
	 * The amount of time the incoming signal is delayed.
	 * @example
	 * const delay = new Tone.Delay().toDestination();
	 * // modulate the delayTime between 0.1 and 1 seconds
	 * const delayLFO = new Tone.LFO(0.5, 0.1, 1).start().connect(delay.delayTime);
	 * const pulse = new Tone.PulseOscillator().connect(delay).start();
	 * // the change in delayTime causes the pitch to go up and down
	 */
	readonly delayTime: Param<"time">;

	/**
	 * Private reference to the internal DelayNode
	 */
	private _delayNode: DelayNode;
	readonly input: DelayNode;
	readonly output: DelayNode;

	/**
	 * @param delayTime The delay applied to the incoming signal.
	 * @param maxDelay The maximum delay time.
	 */
	constructor(delayTime?: Time, maxDelay?: Time);
	constructor(options?: Partial<DelayOptions>);
	constructor() {
		const options = optionsFromArguments(Delay.getDefaults(), arguments, [
			"delayTime",
			"maxDelay",
		]);
		super(options);

		const maxDelayInSeconds = this.toSeconds(options.maxDelay);
		this._maxDelay = Math.max(
			maxDelayInSeconds,
			this.toSeconds(options.delayTime)
		);

		this._delayNode =
			this.input =
			this.output =
				this.context.createDelay(maxDelayInSeconds);

		this.delayTime = new Param({
			context: this.context,
			param: this._delayNode.delayTime,
			units: "time",
			value: options.delayTime,
			minValue: 0,
			maxValue: this.maxDelay,
		});

		readOnly(this, "delayTime");
	}

	static getDefaults(): DelayOptions {
		return Object.assign(ToneAudioNode.getDefaults(), {
			delayTime: 0,
			maxDelay: 1,
		});
	}

	/**
	 * The maximum delay time. This cannot be changed after
	 * the value is passed into the constructor.
	 */
	get maxDelay(): Seconds {
		return this._maxDelay;
	}

	/**
	 * Clean up.
	 */
	dispose(): this {
		super.dispose();
		this._delayNode.disconnect();
		this.delayTime.dispose();
		return this;
	}
}

import { expect } from "chai";

