import { PassAudio } from "../../../test/helper/PassAudio.js";
import { Oscillator } from "../../source/oscillator/Oscillator.js";
import { getContext } from "../Global.js";
import { DestinationInstance } from "./Destination.js";

describe("Destination", () => {
	it("creates itself on the context", () => {
		expect(getContext().destination).instanceOf(DestinationInstance);
	});

	it("can be muted and unmuted", () => {
		return Offline((context) => {
			context.destination.mute = false;
			expect(context.destination.mute).to.equal(false);
			context.destination.mute = true;
			expect(context.destination.mute).to.equal(true);
		});
	});

	it("passes audio through", () => {
		return PassAudio((input) => {
			input.toDestination();
		});
	});

	it("passes no audio when muted", async () => {
		const buffer = await Offline((context) => {
			new Oscillator().toDestination().start(0);
			context.destination.mute = true;
		});
		expect(buffer.isSilent()).to.equal(true);
	});

	it("has a master volume control", () => {
		return Offline((context) => {
			context.destination.volume.value = -20;
			expect(context.destination.volume.value).to.be.closeTo(-20, 0.1);
		});
	});

	it("warns when toMaster is called", () => {
		warns(() => {
			const osc = new Oscillator().toMaster();
			osc.dispose();
		});
	});

	it("can get the maxChannelCount", () => {
		return Offline(
			(context) => {
				expect(context.destination.maxChannelCount).to.equal(4);
			},
			0.1,
			4
		);
	});

	it.skip("can set the audio channel configuration", () => {
		return Offline(
			(context) => {
				expect(context.destination.channelCount).to.equal(4);
				context.destination.channelCountMode = "explicit";
				context.destination.channelInterpretation = "discrete";
				expect(context.destination.channelCountMode).to.equal(
					"explicit"
				);
				expect(context.destination.channelInterpretation).to.equal(
					"discrete"
				);
			},
			0.1,
			4
		);
	});

	it("can pass audio through chained nodes", () => {
		return PassAudio((input) => {
			const gain = input.context.createGain();
			input.connect(gain);
			input.context.destination.chain(gain);
		});
	});
});

import { Volume } from "../../component/channel/Volume.js";
import { Decibels } from "../type/Units.js";
import { optionsFromArguments } from "../util/Defaults.js";
import { onContextClose, onContextInit } from "./ContextInitialization.js";
import { Gain } from "./Gain.js";
import { Param } from "./Param.js";
import {
	connectSeries,
	ToneAudioNode,
	ToneAudioNodeOptions,
} from "./ToneAudioNode.js";

interface DestinationOptions extends ToneAudioNodeOptions {
	volume: Decibels;
	mute: boolean;
}

/**
 * A single master output that is connected to the
 * AudioDestinationNode (i.e. your speakers).
 *
 * It provides useful conveniences, such as the ability
 * to set the volume and mute the entire application.
 *
 * It also gives you the ability to apply master effects to your application.
 *
 * @example
 * const oscillator = new Tone.Oscillator().start();
 * // The audio will go from the oscillator to the speakers.
 * oscillator.connect(Tone.getDestination());
 * // A convenience for connecting to the master output is also provided:
 * oscillator.toDestination();
 * @category Core
 */
export class DestinationInstance extends ToneAudioNode<DestinationOptions> {
	readonly name: string = "Destination";

	input: Volume = new Volume({ context: this.context });
	output: Gain = new Gain({ context: this.context });

	/**
	 * The volume of the master output in decibels.
	 *
	 * -Infinity is silent, and 0 is no change.
	 *
	 * @example
	 * const osc = new Tone.Oscillator().toDestination();
	 * osc.start();
	 * // Ramp the volume down to silent over 10 seconds.
	 * Tone.getDestination().volume.rampTo(-Infinity, 10);
	 */
	volume: Param<"decibels"> = this.input.volume;

	constructor(options: Partial<DestinationOptions>);
	constructor() {
		const options = optionsFromArguments(
			DestinationInstance.getDefaults(),
			arguments
		);
		super(options);

		connectSeries(
			this.input,
			this.output,
			this.context.rawContext.destination
		);

		this.mute = options.mute;
		this._internalChannels = [
			this.input,
			this.context.rawContext.destination,
			this.output,
		];
	}

	static getDefaults(): DestinationOptions {
		return Object.assign(ToneAudioNode.getDefaults(), {
			mute: false,
			volume: 0,
		});
	}

	/**
	 * Mute the output.
	 * @example
	 * const oscillator = new Tone.Oscillator().start().toDestination();
	 * setTimeout(() => {
	 * 	// Mute the output.
	 * 	Tone.Destination.mute = true;
	 * }, 1000);
	 */
	get mute(): boolean {
		return this.input.mute;
	}
	set mute(mute: boolean) {
		this.input.mute = mute;
	}

	/**
	 * Add a master effects chain.
	 *
	 * NOTE: This will disconnect any nodes that were previously chained in the master effects chain.
	 *
	 * @param args All arguments will be connected in a row, and the master output will be routed through it.
	 * @example
	 * // Route all audio through a filter and compressor.
	 * const lowpass = new Tone.Filter(800, "lowpass");
	 * const compressor = new Tone.Compressor(-18);
	 * Tone.Destination.chain(lowpass, compressor);
	 */
	chain(...args: Array<AudioNode | ToneAudioNode>): this {
		this.input.disconnect();
		args.unshift(this.input);
		args.push(this.output);
		connectSeries(...args);
		return this;
	}

	/**
	 * The maximum number of channels the system can output.
	 * @example
	 * console.log(Tone.Destination.maxChannelCount);
	 */
	get maxChannelCount(): number {
		return this.context.rawContext.destination.maxChannelCount;
	}

	/**
	 * Clean up
	 */
	dispose(): this {
		super.dispose();
		this.volume.dispose();
		return this;
	}
}

//-------------------------------------
// 	INITIALIZATION
//-------------------------------------

onContextInit((context) => {
	context.destination = new DestinationInstance({ context });
});

onContextClose((context) => {
	context.destination.dispose();
});

