import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { connectFrom, connectTo } from "../../../test/helper/Connect.js";
import { PassAudio } from "../../../test/helper/PassAudio.js";
import { Gain } from "./Gain.js";

describe("Gain", () => {
	BasicTests(Gain);

	it("can be created and disposed", () => {
		const gainNode = new Gain();
		gainNode.dispose();
	});

	it("handles input and output connections", () => {
		const gainNode = new Gain();
		gainNode.connect(connectTo());
		connectFrom().connect(gainNode);
		connectFrom().connect(gainNode.gain);
		gainNode.dispose();
	});

	it("can set the gain value", () => {
		const gainNode = new Gain();
		expect(gainNode.gain.value).to.be.closeTo(1, 0.001);
		gainNode.gain.value = 0.2;
		expect(gainNode.gain.value).to.be.closeTo(0.2, 0.001);
		gainNode.dispose();
	});

	it("can be constructed with options object", () => {
		const gainNode = new Gain({
			gain: 0.4,
		});
		expect(gainNode.gain.value).to.be.closeTo(0.4, 0.001);
		gainNode.dispose();
	});

	it("can be constructed with an initial value", () => {
		const gainNode = new Gain(3);
		expect(gainNode.gain.value).to.be.closeTo(3, 0.001);
		gainNode.dispose();
	});

	it("can set the units", () => {
		const gainNode = new Gain(0, "decibels");
		expect(gainNode.gain.value).to.be.closeTo(0, 0.001);
		expect(gainNode.gain.units).to.equal("decibels");
		gainNode.dispose();
	});

	it("can get the value using 'get'", () => {
		const gainNode = new Gain(5);
		const value = gainNode.get();
		expect(value.gain).to.be.closeTo(5, 0.001);
		gainNode.dispose();
	});

	it("can set the value using 'set'", () => {
		const gainNode = new Gain(5);
		gainNode.set({
			gain: 4,
		});
		expect(gainNode.gain.value).to.be.closeTo(4, 0.001);
		gainNode.dispose();
	});

	it("passes audio through", () => {
		return PassAudio((input) => {
			const gainNode = new Gain().toDestination();
			input.connect(gainNode);
		});
	});
});

import { Param } from "../context/Param.js";
import { UnitMap, UnitName } from "../type/Units.js";
import { optionsFromArguments } from "../util/Defaults.js";
import { readOnly } from "../util/Interface.js";
import { ToneAudioNode, ToneAudioNodeOptions } from "./ToneAudioNode.js";

interface GainOptions<TypeName extends UnitName> extends ToneAudioNodeOptions {
	gain: UnitMap[TypeName];
	units: TypeName;
	convert: boolean;
	minValue?: number;
	maxValue?: number;
}

/**
 * A thin wrapper around the Native Web Audio GainNode.
 * The GainNode is a basic building block of the Web Audio
 * API and is useful for routing audio and adjusting gains.
 * @category Core
 * @example
 * return Tone.Offline(() => {
 * 	const gainNode = new Tone.Gain(0).toDestination();
 * 	const osc = new Tone.Oscillator(30).connect(gainNode).start();
 * 	gainNode.gain.rampTo(1, 0.1);
 * 	gainNode.gain.rampTo(0, 0.4, 0.2);
 * }, 0.7, 1);
 */
export class Gain<
	TypeName extends "gain" | "decibels" | "normalRange" = "gain",
> extends ToneAudioNode<GainOptions<TypeName>> {
	readonly name: string = "Gain";

	/**
	 * The gain parameter of the gain node.
	 * @example
	 * const gainNode = new Tone.Gain(0).toDestination();
	 * const osc = new Tone.Oscillator().connect(gainNode).start();
	 * gainNode.gain.rampTo(1, 0.1);
	 * gainNode.gain.rampTo(0, 2, "+0.5");
	 */
	readonly gain: Param<TypeName>;

	/**
	 * The wrapped GainNode.
	 */
	private _gainNode: GainNode = this.context.createGain();

	// input = output
	readonly input: GainNode = this._gainNode;
	readonly output: GainNode = this._gainNode;

	/**
	 * @param  gain The initial gain of the GainNode
	 * @param units The units of the gain parameter.
	 */
	constructor(gain?: UnitMap[TypeName], units?: TypeName);
	constructor(options?: Partial<GainOptions<TypeName>>);
	constructor() {
		const options = optionsFromArguments(Gain.getDefaults(), arguments, [
			"gain",
			"units",
		]);
		super(options);

		this.gain = new Param({
			context: this.context,
			convert: options.convert,
			param: this._gainNode.gain,
			units: options.units,
			value: options.gain,
			minValue: options.minValue,
			maxValue: options.maxValue,
		});
		readOnly(this, "gain");
	}

	static getDefaults(): GainOptions<any> {
		return Object.assign(ToneAudioNode.getDefaults(), {
			convert: true,
			gain: 1,
			units: "gain",
		});
	}

	/**
	 * Clean up.
	 */
	dispose(): this {
		super.dispose();
		this._gainNode.disconnect();
		this.gain.dispose();
		return this;
	}
}

import { hasAudioContext } from "./AudioContext.js";
import { BaseContext } from "./BaseContext.js";
import { Context } from "./Context.js";
import { DummyContext } from "./DummyContext.js";

/**
 * This dummy context is used to avoid throwing immediate errors when importing in Node.js
 */
export const dummyContext: BaseContext = new DummyContext();

/**
 * The global audio context which is getable and assignable through
 * getContext and setContext
 */
let globalContext: BaseContext = dummyContext;

/**
 * Returns the default system-wide {@link Context}.
 * Auto-initializes a real Context in browser environments.
 */
export function getContext(): BaseContext {
	if (globalContext === dummyContext && hasAudioContext) {
		globalContext = new Context({ clockSource: 'timeout' });
	}
	return globalContext;
}

/**
 * Set the global context directly. Unlike the richer `setContext` in Global.ts,
 * this only accepts a {@link BaseContext} — no native AudioContext wrapping.
 */
export function setContext(context: BaseContext): void {
	globalContext = context;
}

